async function renderedContrast(h){h.r.contrast=[];
 async function sample(label,selector){await h.p.mouse.move(5,5);const e=h.p.locator(selector);await sleep(h.p,450);await e.scrollIntoViewIfNeeded();await sleep(h.p,200);const box=await e.boundingBox();assert.ok(box,label+' visible');const style=await e.evaluate(e=>{const s=getComputedStyle(e);return{color:s.color,fontSize:s.fontSize,fontWeight:s.fontWeight,background:s.backgroundImage,opacity:s.opacity};});const file=h.dir+'/'+label+'.png';await h.p.screenshot({path:file});const py=`import sys,json,collections,math
from PIL import Image
a=json.load(sys.stdin);im=Image.open(a['file']).convert('RGB');b=a['box'];x,y,w,h=[b[k] for k in ['x','y','width','height']];crop=im.crop((int(x),int(y),math.ceil(x+w),math.ceil(y+h)));colors=collections.Counter(crop.getdata());fg=a['foreground'];nearest=min(colors,key=lambda c:sum((c[i]-fg[i])**2 for i in range(3)));bg=next(c for c,n in colors.most_common() if sum((c[i]-fg[i])**2 for i in range(3))>2500);samples=[bg];
for u,v in [(0.12,0.12),(0.5,0.12),(0.88,0.12),(0.12,0.88),(0.5,0.88),(0.88,0.88)]:
 c=im.getpixel((int(x+w*u),int(y+h*v)));
 if sum((c[i]-fg[i])**2 for i in range(3))>2500:samples.append(c)
def lum(c):
 q=[v/255 for v in c];q=[v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in q];return .2126*q[0]+.7152*q[1]+.0722*q[2]
def ratio(c):
 a,b=sorted([lum(nearest),lum(c)]);return (b+.05)/(a+.05)
print(json.dumps({'renderedForeground':nearest,'foregroundPixelCount':colors[nearest],'foregroundDistanceFromCSS':math.sqrt(sum((nearest[i]-fg[i])**2 for i in range(3))),'backgroundMode':bg,'backgroundSamples':samples,'ratios':[ratio(c) for c in samples],'minimumSampledRatio':min(ratio(c) for c in samples)}))`;
 const foreground=style.color.match(/[\d.]+/g).slice(0,3).map(Number);const result=spawnSync('python3',['-c',py],{input:JSON.stringify({file,box,foreground}),encoding:'utf8'});assert.equal(result.status,0,result.stderr);const measurement=JSON.parse(result.stdout);assert.ok(measurement.foregroundDistanceFromCSS<=3&&measurement.foregroundPixelCount>=2,'Rendered foreground not found; invalidate sample rather than infer contrast');const size=parseFloat(style.fontSize),large=size>=24||(size>=18.66&&Number(style.fontWeight)>=700),required=large?3:4.5;h.r.contrast.push({label,selector,box,style,...measurement,required,meetsSampledRequirement:measurement.minimumSampledRatio>=required,method:'Actual screenshot RGB pixels; nearest foreground core to computed text color, dominant and six inset background samples. Not whole-gradient or all glyph audit.'});}
 await sample('paper-key-text','#region-name');await sample('toolbar-text','[data-panel="workshop"]');await h.key('Escape');await sample('coral-primary','[data-modal-action="play"]');await h.click('[data-modal-action="play"]');await h.key('b');await sample('disabled-explanation','#recipe-reason-waterwheel');await h.click('#close-panel');for(const m of h.r.contrast)h.check('Sampled contrast '+m.label,m.meetsSampledRequirement,m);
}

