async function homeCornerDive(h){const ctx=Game.getContext(await h.state());h.check('Home timber hull corner exceeds old center circle',ctx.nearest.id==='home-timber'&&ctx.nearest.inReach&&ctx.nearest.distance>4.5,ctx.nearest);await h.shot('home-corner-dive-label');const text=await h.p.locator('#dive-button').innerText();h.check('Dive button names resource instead of nearby reef',/timber/i.test(text)&&!/Home Reef/i.test(text),text);const position=(await h.state()).position;await h.key('Space');h.check('Space enters exact resource adapter',(await h.state()).cleanup.attempt?.siteId==='salvage:home-timber');h.check('Entry never teleports raft',JSON.stringify((await h.state()).position)===JSON.stringify(position));await h.shot('home-corner-actual-entry');await finishSite(h);await exit(h);await noDuplicateReload(h,'home-timber');}
async function cleanCopy(h){await openComparison(h);await h.p.locator('#compare-action').selectOption('clean');await h.p.locator('#comparison-panel').waitFor({state:'visible'});await sleep(h.p,450);const text=await h.p.locator('#comparison-panel').innerText();h.check('Panel explains three bands, stationary limit and E fallback',/all three dirty bands/.test(text)&&/one spot only cleans that band/.test(text)&&/automatic sweep/.test(text),text);await h.shot('clean-instructions-panel');await h.click('[data-modal-action="comparison-done"]');await h.key('Space');h.check('HUD instructs sweep and accessible E',/sweep across all dirty bands.*Hold E to auto-sweep/.test(await h.p.locator('#context-hint').innerText()));await h.shot('clean-instructions-hud');const item=Game.getCleanupSite(await h.state()).trash[0];await swim(h,item);await targetHold(h,item,1100);h.check('Stationary clean does not win',!(await h.state()).cleanup.attempt.collected.includes(item.id));await h.shot('stationary-one-band');await workTarget(h,item);h.check('Actual sweep resolves stationary stall',(await h.state()).cleanup.attempt.collected.includes(item.id));await h.shot('sweep-complete');}
async function finalSmoke(h){h.check('Fresh smoke storage empty',h.r.initialStorage.length===0);await sail(h,{x:3,z:1},{tolerance:.4});await h.key('e');h.check('Actual starter pickup',(await h.state()).collected.includes('home-driftwood'));await enterSite(h,'home-reef');await finishSite(h);await exit(h);const before=await h.state();await saveReload(h);h.check('Final source earned smoke persists',JSON.stringify((await h.state()).inventory)===JSON.stringify(before.inventory)&&(await h.state()).cleanup.completed.includes('home-reef'));await h.shot('final-smoke-continued');}

async function performance(h,override){const view=override??option('perf-view','follow');assert.ok(['follow','helm','cleanup'].includes(view));await h.key('Escape');await h.click('[data-modal-action="settings"]');await h.p.locator('#quality-setting').selectOption('high');await h.click('[data-modal-action="settings-done"]');await h.click('[data-modal-action="play"]');await compare(h,{camera:view==='helm'?'helm':'follow'});if(view==='cleanup')await h.key('Space');else await helm(h);if(args.includes('--headed'))await h.p.bringToFront();h.check('Benchmark page visible and focused',await h.p.evaluate(()=>document.visibilityState==='visible'&&document.hasFocus()));await sleep(h.p,5000);const before=await metrics(h.p);h.check('Benchmark DPR1 High',before.quality==='high'&&before.viewport.devicePixelRatio===1);const sample=await h.p.evaluate(()=>new Promise(resolve=>{const intervals=[];let last;const start=performance.now();function frame(t){if(last!==undefined)intervals.push(t-last);last=t;if(t-start>=20000)resolve({elapsedMs:t-start,intervals,visibility:document.visibilityState});else requestAnimationFrame(frame);}requestAnimationFrame(frame);}));const sorted=[...sample.intervals].sort((a,b)=>a-b),pct=p=>sorted[Math.ceil(sorted.length*p)-1];const software=/swiftshader|llvmpipe|software/i.test(JSON.stringify(h.r.graphics));h.r.benchmark={warmupMs:5000,durationMs:sample.elapsedMs,view,stationary:true,video:false,screenshotsDuringSample:false,software,hardwareRendererReported:!software,headless:report.headless,medianMs:pct(.5),p95Ms:pct(.95),framesOver50ms:sorted.filter(x=>x>50).length,before,after:await metrics(h.p),...sample,budgetMet:!software&&pct(.5)<=20&&pct(.95)<=33.4,caveat:'rAF intervals, not GPU timings. Headless hardware result identified separately from headed result.'};h.check('Visible uninterrupted sample',sample.visibility==='visible'&&!(await metrics(h.p)).paused);if(!software)h.check('Hardware frame interval budget',h.r.benchmark.budgetMet);}
try{
 if(mode==='performance'){for(const view of (option('perf-view')==='all'?['follow','helm','cleanup']:[option('perf-view','follow')]))await run('hardware-'+view,h=>performance(h,view));}
 else {const chosen=name=>suite==='all'||suite.split(',').includes(name); if(suite.split(',').includes('gate'))await run('gate-negative-radial-motion',gate,{fixture:fixture('Controlled current contact at (0,21.9), no wheel; not earned arc',s=>{s.position={x:0,z:21.9};}),video:true}); if(chosen('earned'))for(const viewport of [{width:1440,height:900},{width:900,height:900}].filter(v=>option('earned-layout')!=='wide'||v.width===1440))await run('earned-'+viewport.width+'x'+viewport.height,earned,{viewport});if(chosen('variants'))await variants();if(chosen('lifecycle')){await run('lifecycle',lifecycle);await run('practice-new-voyage-save',practiceNewVoyage);}if(chosen('cameras'))for(const viewport of [{width:1440,height:900},{width:900,height:900}])await run('cameras-'+viewport.width+'x'+viewport.height,cameras,{viewport,video:true});if(chosen('targets')){await targets();await regionEdge();}if(chosen('mangrove'))await mangrove();if(chosen('footprint'))await finalFootprint();if(chosen('home-corner'))await run('home-timber-corner-dive',homeCornerDive,{fixture:fixture('TR5 high tide Home timber corner within Home Reef entry radius; candidate reconstruction',s=>{s.position={x:2.6,z:1.7};s.heading=0;s.time=90;s.collected=['home-driftwood','home-crate'];s.inventory={wood:4,scrap:3,pearls:0};s.stats.gathered={wood:4,scrap:3,pearls:0};}),video:true});if(chosen('clean-copy'))await run('clean-instructions-actual-sweep',cleanCopy,{video:true});if(chosen('smoke'))await run('final-earned-smoke',finalSmoke);if(chosen('home-copy')){const path='captures/third-improvement/qa/2026-10-09T02-42-56.758Z-evidence/results.json';const prior=JSON.parse(await readFile(path,'utf8'));const seed=prior.cases.find(c=>c.name==='earned-1440x900').observations.at(-1).state;await run('earned-home-copy-continuation',homeCopy,{fixture:{label:'Continuation from actual refined earned arc at home; source '+path+'; no fabricated progression',state:seed}});}if(chosen('audio'))await run('audio-state',audioState);if(chosen('resources'))await run('repeated-resource-transitions',resourceTransitions);if(chosen('contrast'))await run('rendered-contrast',renderedContrast);if(chosen('adapters'))await adapters();if(chosen('accessibility'))for(const viewport of [{width:1440,height:900},{width:900,height:900}])await run('accessibility-'+viewport.width+'x'+viewport.height,accessibility,{viewport});assert.ok(report.cases.length,'Unknown suite');}
}finally{await browser.close();report.after=await fingerprint();report.buildUnchanged=report.before.hash===report.after.hash;report.completedAt=new Date().toISOString();report.status=report.buildUnchanged&&report.cases.every(c=>c.status==='pass')?'pass':'fail';await writeFile(out+'/results.json',JSON.stringify(report,null,2));console.log(out);if(report.status!=='pass')process.exitCode=1;}
